import { flushQueue } from "./queue";

let isFlushing = false;

export function setupOfflineSync(getAuthHeaders) {
  async function attemptFlush() {
    if (isFlushing) return;
    if (!navigator.onLine) return;
    if (document.visibilityState === "hidden") return;
    isFlushing = true;
    try {
      await flushQueue(getAuthHeaders);
    } finally {
      isFlushing = false;
    }
  }

  window.addEventListener("online", attemptFlush);
  window.addEventListener("focus", attemptFlush);
  // Optional periodic flush (disabled by default to avoid refresh feel)
  // If needed, you can re-enable with window.__ENABLE_PERIODIC_SYNC__ = true
  let intervalId = null;
  const maybeStartInterval = () => {
    if (window.__ENABLE_PERIODIC_SYNC__ && !intervalId) {
      intervalId = setInterval(attemptFlush, 60000);
    }
  };
  maybeStartInterval();
  // React to runtime toggling
  window.addEventListener("toggle-periodic-sync", maybeStartInterval);
  attemptFlush();
}
